import { Client } from "@stomp/stompjs";
import SockJS from "sockjs-client";

const BASE = process.env.REACT_APP_API_URL || "http://localhost:8080";

class WSService {
  constructor() {
    this.client       = null;
    this.subscriptions = {};   // key → STOMP sub object
    this.pendingSubs   = {};   // key → callback (replayed on reconnect)
    this.onConnectCb    = null;
    this.onDisconnectCb = null;
  }

  connect(token, onConnect, onDisconnect) {
    this.onConnectCb    = onConnect;
    this.onDisconnectCb = onDisconnect;

    this.client = new Client({
      webSocketFactory: () => new SockJS(`${BASE}/ws`),
      connectHeaders:   { Authorization: `Bearer ${token}` },
      reconnectDelay:   3000,
      onConnect: () => {
        if (this.onConnectCb) this.onConnectCb();
        // Re-subscribe everything after reconnect
        Object.entries(this.pendingSubs).forEach(([key, { topic, cb }]) => {
          this._doSubscribe(key, topic, cb);
        });
      },
      onDisconnect: () => {
        this.subscriptions = {};
        if (this.onDisconnectCb) this.onDisconnectCb();
      },
      onStompError: (frame) => console.error("STOMP error", frame),
    });

    this.client.activate();
  }

  disconnect() {
    this.subscriptions = {};
    this.pendingSubs   = {};
    if (this.client) { this.client.deactivate(); this.client = null; }
  }

  // ── Internal subscribe helper ───────────────────────────────────────────────
  _doSubscribe(key, topic, callback) {
    if (!this.client?.connected) return;
    if (this.subscriptions[key]) return;
    this.subscriptions[key] = this.client.subscribe(topic, (frame) => {
      try { callback(JSON.parse(frame.body)); } catch (e) { console.error(e); }
    });
  }

  // ── Public: subscribe to chat messages for a room ──────────────────────────
  subscribeRoom(roomId, callback) {
    const key   = `room:${roomId}`;
    const topic = `/topic/room/${roomId}`;
    this.pendingSubs[key] = { topic, cb: callback };
    if (this.client?.connected) this._doSubscribe(key, topic, callback);
  }

  // ── Feature: subscribe to typing events for a room ────────────────────────
  subscribeTyping(roomId, callback) {
    const key   = `typing:${roomId}`;
    const topic = `/topic/room/${roomId}/typing`;
    this.pendingSubs[key] = { topic, cb: callback };
    if (this.client?.connected) this._doSubscribe(key, topic, callback);
  }

  unsubscribeRoom(roomId) {
    [`room:${roomId}`, `typing:${roomId}`].forEach((key) => {
      delete this.pendingSubs[key];
      if (this.subscriptions[key]) {
        try { this.subscriptions[key].unsubscribe(); } catch (_) {}
        delete this.subscriptions[key];
      }
    });
  }

  // ── Send a chat message ────────────────────────────────────────────────────
  sendMessage(roomId, content, senderName, senderId) {
    if (!this.client?.connected) return false;
    this.client.publish({
      destination: "/app/chat.sendMessage",
      body: JSON.stringify({ roomId, content, senderName, senderId, type: "CHAT" }),
    });
    return true;
  }

  // ── Feature: publish typing event ─────────────────────────────────────────
  sendTyping(roomId, username, typing) {
    if (!this.client?.connected) return;
    this.client.publish({
      destination: "/app/chat.typing",
      body: JSON.stringify({ roomId, username, typing }),
    });
  }

  // ── Feature: publish reaction ─────────────────────────────────────────────
  sendReaction(messageId, roomId, emoji) {
    if (!this.client?.connected) return;
    this.client.publish({
      destination: "/app/chat.react",
      body: JSON.stringify({ messageId, roomId, emoji }),
    });
  }

  get connected() { return !!this.client?.connected; }
}

export const wsService = new WSService();
